def plan(pg, text='birthday party', typ='birthday', guests=25, setting='indoor', budget=None, keep=True, kids=False, alcohol=None, time=None, city='Houston, TX', hours=None):
    pg.goto(U + '#/new/1'); pg.wait_for_selector('#text'); pg.fill('#text', text); pg.click('#next'); pg.wait_for_selector('#type')
    pg.select_option('#type', typ); pg.fill('#guests', str(guests)); pg.fill('#expected', str(guests)); pg.select_option('#city', city)
    if hours: pg.fill('#hours', str(hours))
    if budget: pg.fill('#budget', str(budget))
    if time: pg.fill('#time', time)
    if kids and not pg.is_checked('#kids'): pg.click('#kids')
    if alcohol: pg.click('#alcohol [data-v=%s]' % alcohol)
    pg.click('#setting [data-v=%s]' % setting); pg.click('#next'); pg.wait_for_selector('.concept'); pg.wait_for_timeout(200)
    pg.click('.concept button >> nth=0'); pg.wait_for_selector('.plan-head')
    if keep: pg.click('#keepBtn'); pg.click('#keepPay'); pg.wait_for_timeout(250)
    return '#/' + '/'.join(pg.url.split('#/')[1].split('/')[:2])
def go(pg, h): pg.goto(U + h); pg.wait_for_timeout(300)
